import {vi} from 'vitest';
const blobMock=vi.hoisted(()=>({objects:new Map<string,Buffer>(),callbacks:0,lastAdmission:null as Record<string,unknown>|null}));
vi.mock('@vercel/blob',()=>{class Conflict extends Error{};return {BlobPreconditionFailedError:Conflict,
 async put(key:string,bytes:Buffer,options:{access:string;allowOverwrite:boolean;addRandomSuffix:boolean}){if(options.access!=='private'||options.allowOverwrite||options.addRandomSuffix)throw Error('Unsafe mocked store request');if(blobMock.objects.has(key))throw new Conflict();blobMock.objects.set(key,Buffer.from(bytes));return {pathname:key};},
 async get(key:string,options:{access:string;useCache:boolean}){if(options.access!=='private'||options.useCache)throw Error('Unsafe mocked store read');const bytes=blobMock.objects.get(key);return bytes?{statusCode:200,headers:new Headers({'content-length':String(bytes.length)}),blob:{pathname:key,size:bytes.length},stream:new ReadableStream({start(c){c.enqueue(bytes);c.close();}})}:null;},
 async del(key:string){blobMock.objects.delete(key);},async list(options:{prefix:string;cursor?:string;limit:number}){const keys=[...blobMock.objects.keys()].filter(k=>k.startsWith(options.prefix)&&(!options.cursor||k>options.cursor)).sort();return {blobs:keys.slice(0,options.limit).map(pathname=>({pathname,size:blobMock.objects.get(pathname)!.length,uploadedAt:new Date()})),hasMore:keys.length>options.limit,cursor:keys[options.limit-1]};}};});
// Simulates delivery after SDK signature verification, not actual provider signature proof.
vi.mock('@vercel/blob/client',()=>({async handleUpload(options:{body:{type:string;payload?:{pathname:string;clientPayload:string;multipart:boolean}};onBeforeGenerateToken:(path:string,payload:string,multipart:boolean)=>Promise<Record<string,unknown>>;onUploadCompleted:()=>Promise<void>}){if(options.body.type==='blob.generate-client-token'){const p=options.body.payload!;blobMock.lastAdmission=await options.onBeforeGenerateToken(p.pathname,p.clientPayload,p.multipart);return {type:'blob.generate-client-token',clientToken:'synthetic-upload-only-token'};}if(options.body.type!=='blob.upload-completed')throw Error('Invalid mocked upload event');blobMock.callbacks++;await options.onUploadCompleted();return {type:'blob.upload-completed'};}}));

export {blobMock};
